using HartsyInference.Core.Backends.Attention;
using HartsyInference.Core.Tensors;
using Xunit;

namespace HartsyInference.Core.Tests.Backends;

/// <summary>The decode merge reference against Comfy Kitchen's torch definitions (sampled outputs in
/// <see cref="DecodeMergeKitchenVectors"/>, generated by benchmarks/attention/kitchen_merge_vectors.py), and against what a
/// merge must equal: ordinary attention over the prefix and the step's rows together.</summary>
public sealed class DecodeMergeReferenceTests
{
    /// <summary>The generator's values in [-1, 1): a 32-bit LCG, exact in F32, identical in the Python script.</summary>
    private static float[] Uniform(int count, uint seed)
    {
        float[] values = new float[count];
        uint state = seed;
        for (int i = 0; i < count; i++)
        {
            state = unchecked(state * 1664525u + 1013904223u);
            values[i] = ((state >> 8) & 0xFFFF) / 32768f - 1f;
        }
        return values;
    }

    private static Tensor Filled(TensorShape shape, uint seed)
    {
        Tensor tensor = new(shape, DType.F32);
        Uniform((int)tensor.ElementCount, seed).CopyTo(tensor.AsSpan<float>());
        return tensor;
    }

    /// <summary>One verify step, built as the generator builds it: queries, a cache of committed keys and values, and the
    /// step's own keys and values.</summary>
    private sealed class Step : IDisposable
    {
        public readonly int Batch, Heads, KvHeads, Dim, Rows, Capacity;
        public readonly Tensor Query, CacheKey, CacheValue, Key, Value, Prefix, Merged;
        public readonly float[] Lse;

        public Step(int batch, int heads, int kvHeads, int dim, int rows, int capacity, uint seed)
        {
            (Batch, Heads, KvHeads, Dim, Rows, Capacity) = (batch, heads, kvHeads, dim, rows, capacity);
            Query = Filled(new TensorShape(batch, heads, rows, dim), seed);
            CacheKey = Filled(new TensorShape(batch, kvHeads, capacity, dim), seed + 1);
            CacheValue = Filled(new TensorShape(batch, kvHeads, capacity, dim), seed + 2);
            Key = Filled(new TensorShape(batch, kvHeads, rows, dim), seed + 3);
            Value = Filled(new TensorShape(batch, kvHeads, rows, dim), seed + 4);
            Prefix = new Tensor(new TensorShape(batch, rows, heads * dim), DType.F32);
            Merged = new Tensor(new TensorShape(batch, rows, heads * dim), DType.F32);
            Lse = new float[batch * heads * rows];
        }

        public float DefaultScale => 1f / MathF.Sqrt(Dim);

        /// <summary>Every row attends the first <c>lengths[b]</c> cache rows of its batch, with no causal rule, in double
        /// precision: the prefix output <c>[B, S, H × D]</c> and its natural-log LSE <c>[B, H, S]</c>.</summary>
        public void DecodePrefix(ReadOnlySpan<int> lengths, float? scale = null)
        {
            double alpha = scale ?? DefaultScale;
            ReadOnlySpan<float> q = Query.AsReadOnlySpan<float>(), k = CacheKey.AsReadOnlySpan<float>(), v = CacheValue.AsReadOnlySpan<float>();
            Span<float> o = Prefix.AsSpan<float>();
            int group = Heads / KvHeads;
            double[] scores = new double[Capacity], acc = new double[Dim];
            for (int b = 0; b < Batch; b++)
                for (int h = 0; h < Heads; h++)
                    for (int r = 0; r < Rows; r++)
                    {
                        int qAt = ((b * Heads + h) * Rows + r) * Dim, outAt = ((b * Rows + r) * Heads + h) * Dim;
                        int keys = lengths[b], kh = h / group;
                        if (keys == 0)
                        {
                            o.Slice(outAt, Dim).Clear();
                            Lse[(b * Heads + h) * Rows + r] = float.NegativeInfinity;
                            continue;
                        }
                        double max = double.NegativeInfinity;
                        for (int j = 0; j < keys; j++)
                        {
                            int kAt = ((b * KvHeads + kh) * Capacity + j) * Dim;
                            double dot = 0;
                            for (int d = 0; d < Dim; d++) dot += (double)q[qAt + d] * k[kAt + d];
                            scores[j] = dot * alpha;
                            max = Math.Max(max, scores[j]);
                        }
                        double total = 0;
                        Array.Clear(acc);
                        for (int j = 0; j < keys; j++)
                        {
                            double weight = Math.Exp(scores[j] - max);
                            total += weight;
                            int vAt = ((b * KvHeads + kh) * Capacity + j) * Dim;
                            for (int d = 0; d < Dim; d++) acc[d] += weight * v[vAt + d];
                        }
                        for (int d = 0; d < Dim; d++) o[outAt + d] = (float)(acc[d] / total);
                        Lse[(b * Heads + h) * Rows + r] = (float)(max + Math.Log(total));
                    }
        }

        public void StepMerge(float? scale = null) => DecodeMergeReference.StepMerge(Merged, Prefix, Lse, Query, Key, Value, scale);

        public void TreeMerge(ReadOnlySpan<int> mask, float? scale = null) =>
            DecodeMergeReference.TreeMerge(Merged, Prefix, Lse, Query, Key, Value, mask, scale);

        /// <summary>Causal attention over the first <paramref name="prefix"/> cache rows followed by the step's rows, by the
        /// host reference: row r sits at position prefix + r. Returned as <c>[B, S, H × D]</c>.</summary>
        public float[] CausalOverPrefixAndStep(int prefix, float scale)
        {
            using Tensor key = new(new TensorShape(Batch, KvHeads, prefix + Rows, Dim), DType.F32);
            using Tensor value = new(new TensorShape(Batch, KvHeads, prefix + Rows, Dim), DType.F32);
            using Tensor output = new(Query.Shape, DType.F32);
            for (int bh = 0; bh < Batch * KvHeads; bh++)
            {
                Join(CacheKey, Key, key, bh);
                Join(CacheValue, Value, value, bh);
            }
            AttentionCall call = AttentionCall.FromFlashAttention(output, Query, key, value, prefix + Rows, causal: true, qOffset: prefix, scale,
                softcap: 0f, sink: null, slidingWindow: 0, alibiSlopes: null);
            AttentionHostReference.Run(in call);
            float[] rowMajor = new float[Batch * Rows * Heads * Dim];
            ReadOnlySpan<float> headMajor = output.AsReadOnlySpan<float>();
            for (int b = 0; b < Batch; b++)
                for (int h = 0; h < Heads; h++)
                    for (int r = 0; r < Rows; r++)
                        headMajor.Slice(((b * Heads + h) * Rows + r) * Dim, Dim).CopyTo(rowMajor.AsSpan(((b * Rows + r) * Heads + h) * Dim, Dim));
            return rowMajor;

            void Join(Tensor cache, Tensor step, Tensor joined, int bh)
            {
                cache.AsReadOnlySpan<float>().Slice(bh * Capacity * Dim, prefix * Dim).CopyTo(joined.AsSpan<float>().Slice(bh * (prefix + Rows) * Dim));
                step.AsReadOnlySpan<float>().Slice(bh * Rows * Dim, Rows * Dim)
                    .CopyTo(joined.AsSpan<float>().Slice((bh * (prefix + Rows) + prefix) * Dim));
            }
        }

        public void Dispose()
        {
            foreach (Tensor tensor in (ReadOnlySpan<Tensor>)[Query, CacheKey, CacheValue, Key, Value, Prefix, Merged]) tensor.Dispose();
        }
    }

    private static void AssertClose(ReadOnlySpan<float> expected, ReadOnlySpan<float> actual, double tolerance, string what)
    {
        Assert.Equal(expected.Length, actual.Length);
        for (int i = 0; i < expected.Length; i++)
            Assert.True(Math.Abs(expected[i] - actual[i]) <= tolerance * Math.Max(1.0, Math.Abs(expected[i])),
                $"{what}: element {i} is {actual[i]}, expected {expected[i]}");
    }

    /// <summary>Runs one generator case and compares the prefix LSE and the sampled merged output with the Kitchen's.</summary>
    private static void AssertMatchesKitchen(int index, int batch, int heads, int kvHeads, int dim, int rows, int capacity, int[] lengths,
        int[]? mask, uint[] expectedMerged, uint[] expectedLse)
    {
        using Step step = new(batch, heads, kvHeads, dim, rows, capacity, (uint)(4000 + 100 * index));
        step.DecodePrefix(lengths);
        Assert.Equal(expectedLse.Length, step.Lse.Length);
        for (int i = 0; i < expectedLse.Length; i++)
        {
            float expected = BitConverter.UInt32BitsToSingle(expectedLse[i]);
            if (float.IsNegativeInfinity(expected))
                Assert.True(float.IsNegativeInfinity(step.Lse[i]), $"LSE {i} is {step.Lse[i]}, expected negative infinity");
            else
                Assert.True(Math.Abs(expected - step.Lse[i]) <= 2e-5 * Math.Max(1f, Math.Abs(expected)), $"LSE {i} is {step.Lse[i]}, expected {expected}");
        }
        if (mask is null) step.StepMerge();
        else step.TreeMerge(mask);
        ReadOnlySpan<float> merged = step.Merged.AsReadOnlySpan<float>();
        int width = heads * dim, sampled = width / DecodeMergeKitchenVectors.ChannelStep;
        Assert.Equal(batch * rows * sampled, expectedMerged.Length);
        for (int row = 0; row < batch * rows; row++)
            for (int c = 0; c < sampled; c++)
            {
                float expected = BitConverter.UInt32BitsToSingle(expectedMerged[row * sampled + c]);
                float actual = merged[row * width + c * DecodeMergeKitchenVectors.ChannelStep];
                Assert.True(Math.Abs(expected - actual) <= 2e-5,
                    $"row {row}, channel {c * DecodeMergeKitchenVectors.ChannelStep}: {actual}, expected {expected}");
            }
    }

    [Fact]
    public void ACausalStepMatchesTheKitchen() =>
        AssertMatchesKitchen(0, 1, 4, 2, 64, 5, 48, [40], null, DecodeMergeKitchenVectors.StepCausal, DecodeMergeKitchenVectors.StepCausalLse);

    [Fact]
    public void AGroupedStepOverBatchesOfDifferentLengthsMatchesTheKitchen() =>
        AssertMatchesKitchen(1, 2, 6, 2, 64, 4, 40, [33, 17], null, DecodeMergeKitchenVectors.StepGroupedBatches,
            DecodeMergeKitchenVectors.StepGroupedBatchesLse);

    [Fact]
    public void ASingleRowStepMatchesTheKitchen() =>
        AssertMatchesKitchen(2, 1, 4, 4, 128, 1, 32, [32], null, DecodeMergeKitchenVectors.StepSingleRow, DecodeMergeKitchenVectors.StepSingleRowLse);

    [Fact]
    public void ATreeOfBranchesMatchesTheKitchen() =>
        AssertMatchesKitchen(3, 1, 4, 2, 64, 6, 48, [29], [0b000001, 0b000011, 0b000101, 0b001011, 0b010101, 0b100101],
            DecodeMergeKitchenVectors.TreeBranches, DecodeMergeKitchenVectors.TreeBranchesLse);

    [Fact]
    public void ATreeWithARowThatSeesNoStepRowMatchesTheKitchen() =>
        AssertMatchesKitchen(4, 1, 4, 1, 64, 4, 24, [24], [0b0001, 0b0000, 0b0101, 0b1101],
            DecodeMergeKitchenVectors.TreeWithARowThatSeesNoStepRow, DecodeMergeKitchenVectors.TreeWithARowThatSeesNoStepRowLse);

    [Fact]
    public void AStepOverAnEmptyPrefixMatchesTheKitchen() =>
        AssertMatchesKitchen(5, 2, 4, 2, 64, 3, 16, [0, 9], null, DecodeMergeKitchenVectors.StepOverAnEmptyPrefix,
            DecodeMergeKitchenVectors.StepOverAnEmptyPrefixLse);

    [Theory]
    [InlineData(1, 4, 2, 64, 5, 37, false)]
    [InlineData(2, 6, 3, 32, 7, 20, false)]
    [InlineData(1, 8, 1, 128, 3, 64, true)]
    [InlineData(1, 2, 2, 16, 32, 9, false)]
    public void AStepMergeIsCausalAttentionOverThePrefixAndTheStep(int batch, int heads, int kvHeads, int dim, int rows, int prefix, bool customScale)
    {
        using Step step = new(batch, heads, kvHeads, dim, rows, prefix + 3, 700);
        float scale = customScale ? 0.21f : step.DefaultScale;
        int[] lengths = new int[batch];
        Array.Fill(lengths, prefix);
        step.DecodePrefix(lengths, scale);
        step.StepMerge(customScale ? scale : null);
        AssertClose(step.CausalOverPrefixAndStep(prefix, scale), step.Merged.AsReadOnlySpan<float>(), 2e-5, "step merge");
    }

    [Fact]
    public void OverAnEmptyPrefixAStepMergeIsCausalAttentionOverTheStepAlone()
    {
        using Step step = new(2, 4, 2, 64, 6, 8, 710);
        step.DecodePrefix([0, 0]);
        step.StepMerge();
        AssertClose(step.CausalOverPrefixAndStep(0, step.DefaultScale), step.Merged.AsReadOnlySpan<float>(), 2e-5, "empty prefix");
    }

    [Fact]
    public void ARowWhoseMaskIsEmptyKeepsItsPrefixOutputBitForBit()
    {
        using Step step = new(1, 4, 2, 64, 5, 30, 720);
        step.DecodePrefix([30]);
        step.TreeMerge([0b00001, 0, 0b00101, 0, 0b10001]);
        ReadOnlySpan<float> prefix = step.Prefix.AsReadOnlySpan<float>(), merged = step.Merged.AsReadOnlySpan<float>();
        int width = 4 * 64;
        foreach (int row in (ReadOnlySpan<int>)[1, 3])
            Assert.True(prefix.Slice(row * width, width).SequenceEqual(merged.Slice(row * width, width)), $"row {row} changed");
        Assert.False(prefix.Slice(0, width).SequenceEqual(merged.Slice(0, width)));
    }

    [Fact]
    public void ARowWithNoKeyAtAllIsZero()
    {
        using Step step = new(1, 4, 2, 64, 3, 8, 730);
        step.DecodePrefix([0]);
        step.Merged.AsSpan<float>().Fill(7f);
        step.TreeMerge([0b001, 0, 0b101]);
        ReadOnlySpan<float> merged = step.Merged.AsReadOnlySpan<float>();
        int width = 4 * 64;
        Assert.Equal(-1, merged.Slice(width, width).IndexOfAnyExcept(0f));
        Assert.NotEqual(-1, merged.Slice(0, width).IndexOfAnyExcept(0f));
        Assert.Equal(-1, merged.IndexOf(7f));
    }

    [Fact]
    public void AStepRowTheMaskDoesNotNameIsNotRead()
    {
        int[] mask = [0b0001, 0b0011, 0b0101, 0b1101];
        using Step step = new(1, 4, 2, 64, 4, 20, 740);
        step.DecodePrefix([20]);
        step.TreeMerge(mask);
        float[] before = step.Merged.AsReadOnlySpan<float>().ToArray();
        // Step row 1 is named by row 1 only: rows 0, 2 and 3 must not move when it changes.
        for (int kh = 0; kh < 2; kh++)
        {
            step.Key.AsSpan<float>().Slice((kh * 4 + 1) * 64, 64).Fill(3f);
            step.Value.AsSpan<float>().Slice((kh * 4 + 1) * 64, 64).Fill(-5f);
        }
        step.TreeMerge(mask);
        ReadOnlySpan<float> after = step.Merged.AsReadOnlySpan<float>();
        int width = 4 * 64;
        foreach (int row in (ReadOnlySpan<int>)[0, 2, 3])
            Assert.True(before.AsSpan(row * width, width).SequenceEqual(after.Slice(row * width, width)), $"row {row} moved");
        Assert.False(before.AsSpan(width, width).SequenceEqual(after.Slice(width, width)));
    }

    [Fact]
    public void MergingInPlaceGivesTheSameResult()
    {
        using Step step = new(2, 4, 2, 64, 5, 25, 750);
        step.DecodePrefix([25, 11]);
        step.StepMerge();
        float[] separate = step.Merged.AsReadOnlySpan<float>().ToArray();
        DecodeMergeReference.StepMerge(step.Prefix, step.Prefix, step.Lse, step.Query, step.Key, step.Value);
        Assert.True(separate.AsSpan().SequenceEqual(step.Prefix.AsReadOnlySpan<float>()));
    }

    [Fact]
    public void TheCausalStepMaskNamesEveryRowUpToItself()
    {
        Assert.Equal([0b1, 0b11, 0b111, 0b1111], DecodeMergeReference.CausalStepMask(4));
        int[] full = DecodeMergeReference.CausalStepMask(32);
        Assert.Equal(int.MaxValue, full[30]);
        Assert.Equal(-1, full[31]);
        Assert.Throws<ArgumentOutOfRangeException>(() => DecodeMergeReference.CausalStepMask(0));
        Assert.Throws<ArgumentOutOfRangeException>(() => DecodeMergeReference.CausalStepMask(33));
    }

    [Fact]
    public void MalformedCallsAreRefused()
    {
        using Step step = new(1, 4, 2, 64, 4, 12, 760);
        step.DecodePrefix([12]);
        int[] mask = DecodeMergeReference.CausalStepMask(4);
        float[] lse = step.Lse;
        Tensor merged = step.Merged, prefix = step.Prefix, q = step.Query, k = step.Key, v = step.Value;

        using Tensor headMajor = new(q.Shape, DType.F32);
        Assert.Throws<ArgumentException>(() => DecodeMergeReference.TreeMerge(headMajor, prefix, lse, q, k, v, mask));
        Assert.Throws<ArgumentException>(() => DecodeMergeReference.TreeMerge(merged, headMajor, lse, q, k, v, mask));
        using Tensor half = new(merged.Shape, DType.F16);
        Assert.Throws<ArgumentException>(() => DecodeMergeReference.TreeMerge(half, prefix, lse, q, k, v, mask));
        using Tensor fiveRows = new(new TensorShape(1, 2, 5, 64), DType.F32);
        Assert.Throws<ArgumentException>(() => DecodeMergeReference.TreeMerge(merged, prefix, lse, q, fiveRows, fiveRows, mask));
        using Tensor threeKvHeads = new(new TensorShape(1, 3, 4, 64), DType.F32);
        Assert.Throws<ArgumentException>(() => DecodeMergeReference.TreeMerge(merged, prefix, lse, q, threeKvHeads, threeKvHeads, mask));
        Assert.Throws<ArgumentException>(() => DecodeMergeReference.TreeMerge(merged, prefix, lse, q, k, step.CacheValue, mask));

        Assert.Throws<ArgumentException>(() => DecodeMergeReference.TreeMerge(merged, prefix, lse.AsSpan(1), q, k, v, mask));
        Assert.Throws<ArgumentException>(() => DecodeMergeReference.TreeMerge(merged, prefix, lse, q, k, v, mask.AsSpan(1)));
        Assert.Throws<ArgumentException>(() => DecodeMergeReference.TreeMerge(merged, prefix, lse, q, k, v, [1, 3, 7, 0b10000]));
        Assert.Throws<ArgumentException>(() => DecodeMergeReference.TreeMerge(merged, prefix, lse, q, k, v, [1, 3, 7, -1]));
        Assert.Throws<ArgumentException>(() => DecodeMergeReference.TreeMerge(merged, prefix, lse, q, k, v, mask, float.NaN));
        Assert.Throws<ArgumentException>(() => DecodeMergeReference.StepMerge(merged, prefix, lse, q, k, v, float.PositiveInfinity));

        float[] notANumber = (float[])lse.Clone();
        notANumber[3] = float.NaN;
        Assert.Throws<ArgumentException>(() => DecodeMergeReference.TreeMerge(merged, prefix, notANumber, q, k, v, mask));
        notANumber[3] = float.PositiveInfinity;
        Assert.Throws<ArgumentException>(() => DecodeMergeReference.TreeMerge(merged, prefix, notANumber, q, k, v, mask));

        using Step tooLong = new(1, 1, 1, 8, 33, 4, 770);
        Assert.Throws<ArgumentException>(() =>
            DecodeMergeReference.TreeMerge(tooLong.Merged, tooLong.Prefix, tooLong.Lse, tooLong.Query, tooLong.Key, tooLong.Value, new int[33]));
    }
}
